<?php
require_once __DIR__.'/includes/auth.php';require_manager();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'save';$id=(int)($_POST['id']??0);
 if($action==='delete'){$s=$pdo->prepare('DELETE FROM salary_components WHERE id=?');$s->execute([$id]);set_flash('Komponen berjaya dipadam.');header('Location: components.php');exit;}
 $eid=(int)($_POST['employee_id']??0);$type=$_POST['component_type']??'';$name=trim($_POST['component_name']??'');$amount=(float)($_POST['amount']??0);$month=$_POST['component_month']??'';
 if(!$eid||!in_array($type,['allowance','deduction'],true)||$name===''||$amount<0||!preg_match('/^\d{4}-\d{2}$/',$month)){set_flash('Maklumat tidak sah.','danger');}
 elseif($id){$s=$pdo->prepare('UPDATE salary_components SET employee_id=?,component_type=?,component_name=?,amount=?,component_month=? WHERE id=?');$s->execute([$eid,$type,$name,$amount,$month,$id]);set_flash('Komponen berjaya dikemas kini.');}
 else{$s=$pdo->prepare('INSERT INTO salary_components(employee_id,component_type,component_name,amount,component_month) VALUES(?,?,?,?,?)');$s->execute([$eid,$type,$name,$amount,$month]);set_flash('Komponen gaji berjaya ditambah.');}
 header('Location: components.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM salary_components WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch(PDO::FETCH_ASSOC);}
$employees=$pdo->query("SELECT id,employee_code,full_name FROM employees WHERE employment_status='active' ORDER BY full_name")->fetchAll(PDO::FETCH_ASSOC);
$rows=$pdo->query('SELECT c.*,e.employee_code,e.full_name FROM salary_components c JOIN employees e ON e.id=c.employee_id ORDER BY c.component_month DESC,c.id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
require __DIR__.'/includes/layout.php';page_start('Elaun & Potongan','components');?>
<div class="page-intro"><div><h2>Elaun & potongan</h2><p>Urus komponen gaji pekerja mengikut bulan. Rekod boleh ditambah, diedit atau dipadam.</p></div></div>
<div class="row g-4"><div class="col-xl-4"><div class="panel-card"><h3 class="mb-3"><?=$edit?'Edit komponen':'Tambah komponen'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>">
<label class="form-label">Pekerja</label><select class="form-select mb-3" name="employee_id" required><option value="">Pilih pekerja</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=((int)($edit['employee_id']??0)===(int)$e['id'])?'selected':''?>><?=h($e['employee_code'].' - '.$e['full_name'])?></option><?php endforeach;?></select>
<label class="form-label">Jenis</label><select class="form-select mb-3" name="component_type"><option value="allowance" <?=($edit['component_type']??'allowance')==='allowance'?'selected':''?>>Elaun</option><option value="deduction" <?=($edit['component_type']??'')==='deduction'?'selected':''?>>Potongan</option></select>
<label class="form-label">Nama komponen</label><input class="form-control mb-3" name="component_name" value="<?=h($edit['component_name']??'')?>" placeholder="Contoh: Elaun makan" required>
<label class="form-label">Jumlah (RM)</label><input class="form-control mb-3" type="number" min="0" step=".01" name="amount" value="<?=h($edit['amount']??'')?>" required>
<label class="form-label">Bulan</label><input class="form-control mb-3" type="month" name="component_month" value="<?=h($edit['component_month']??date('Y-m'))?>" required><button class="btn btn-primary w-100" name="action" value="save">Simpan komponen</button><?php if($edit):?><a class="btn btn-light w-100 mt-2" href="components.php">Batal edit</a><?php endif;?></form></div></div>
<div class="col-xl-8"><div class="panel-card"><h3 class="mb-3">Senarai komponen</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Bulan</th><th>Pekerja</th><th>Jenis</th><th>Komponen</th><th>Jumlah</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['component_month'])?></td><td><?=h($r['employee_code'].' - '.$r['full_name'])?></td><td><span class="badge <?=$r['component_type']==='allowance'?'bg-success':'bg-warning text-dark'?>"><?=h(ucfirst($r['component_type']))?></span></td><td><?=h($r['component_name'])?></td><td class="money">RM <?=number_format((float)$r['amount'],2)?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="components.php?edit=<?=(int)$r['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Padam komponen ini?')"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="action" value="delete">Padam</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center muted">Tiada komponen direkodkan.</td></tr><?php endif;?></tbody></table></div></div></div></div><?php page_end();?>
